INSERT INTO jobs (id, title, department, employment_type, workplace_type, location, experience_level, salary_range, featured, skills, summary, about_role, responsibilities, requirements, benefits, deadline, status, created_at, updated_at) VALUES ('frontend-engineer-react', 'Frontend Engineer (React / Next.js)', 'Software Development', 'Full-time', 'Hybrid', 'Hyderabad / Remote', '1–3 Years', '₹6,00,000 – ₹10,00,000 / year', TRUE, 'React, Next.js, TypeScript, Tailwind CSS, GSAP', 'Architect high-performance web applications, fluid micro-interactions, and enterprise design systems with sub-second page performance.', 'As a Frontend Engineer at KODEWAR, you will build user-facing platforms for global clients and internal products. You will work closely with product designers to translate Figma design tokens into clean, performant React components.', 'Build responsive, production-ready user interfaces using React, Next.js, and TypeScript.
Implement fluid animations and micro-interactions utilizing GSAP and CSS transforms.
Collaborate with UI/UX designers to translate Figma tokens into scalable component libraries.
Optimize web applications for peak Core Web Vitals and accessibility standards.', 'Proficiency in React, modern JavaScript (ES6+), and CSS/Tailwind.
Experience with state management, asynchronous data fetching, and RESTful APIs.
Strong eye for spacing, typography, and micro-interactions.
Portfolio or GitHub repositories demonstrating real deployed projects.', 'Work on live production platforms across multiple continents.
Direct 1-on-1 code reviews and architectural mentorship.
High-velocity shipping culture without bureaucratic friction.
Continuous hardware and learning stipend support.', '2026-12-31', 'PUBLISHED', '2026-10-02T06:14:11.304Z', '2026-10-02T06:14:11.304Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO jobs (id, title, department, employment_type, workplace_type, location, experience_level, salary_range, featured, skills, summary, about_role, responsibilities, requirements, benefits, deadline, status, created_at, updated_at) VALUES ('fullstack-developer-mern', 'Full Stack Developer (Node.js & React)', 'Software Development', 'Full-time', 'In-Studio', 'Hyderabad', '2–4 Years', '₹8,00,000 – ₹14,00,000 / year', TRUE, 'Node.js, Express, React, PostgreSQL, REST APIs', 'Lead end-to-end development of client-facing platforms, secure API microservices, and robust relational data pipelines.', 'Join our core platform engineering team in Madhapur, Hyderabad. You will architect resilient backend services, design optimized database schemas, and deliver polished web interfaces.', 'Design, develop, and maintain resilient Node.js / Express microservices and REST APIs.
Architect relational database schemas in PostgreSQL / MySQL with optimized indexing.
Integrate third-party payment gateways, authentication providers, and webhooks.
Participate in agile sprint ceremonies, peer code reviews, and architecture spikes.', 'Demonstrated experience building and maintaining full-stack web applications.
Strong grasp of backend architectural patterns, JWT authentication, and database modeling.
Familiarity with containerization (Docker) and cloud deployments.', 'Direct ownership of entire product features from inception to deployment.
Collaborative engineering squad alongside experienced leads.
Merit-driven compensation and accelerated career progression.
Studio workplace in Madhapur, Hyderabad with hybrid flexibility.', '2026-12-31', 'PUBLISHED', '2026-10-02T06:14:11.304Z', '2026-10-02T06:14:11.304Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO jobs (id, title, department, employment_type, workplace_type, location, experience_level, salary_range, featured, skills, summary, about_role, responsibilities, requirements, benefits, deadline, status, created_at, updated_at) VALUES ('ui-ux-product-designer', 'UI/UX Product Designer', 'UI/UX & Design', 'Full-time', 'Hybrid', 'Hyderabad / Remote', '2–4 Years', '₹6,50,000 – ₹11,00,000 / year', TRUE, 'Figma, Design Systems, Wireframing, UX Research, Micro-interactions', 'Craft high-conversion product interfaces, interactive design tokens, and user research archetypes for complex digital ecosystems.', 'Work at the intersection of aesthetic craft and usability. You will lead interface architecture across web, mobile, and SaaS dashboards.', 'Translate ambiguous client requirements into clear wireframes, user journeys, and mockups.
Maintain and evolve the KODEWAR design system and component tokens in Figma.
Conduct usability audits, prototype micro-interactions, and hand off specifications to frontend engineers.
Iterate based on qualitative client feedback and quantitative product telemetry.', 'High-caliber portfolio showcasing shipped web apps, mobile apps, or design systems.
Mastery of Figma, Auto-layout, component variants, and interactive prototyping.
Deep understanding of responsive grid systems, typography hierarchy, and accessibility.
Ability to articulate design trade-offs with clarity to cross-functional teams.', 'Creative autonomy on flagship international client platforms.
Close collaboration with engineering to ensure 100% design fidelity in production.
Modern equipment setup and Figma organization sponsorship.', '2026-12-31', 'PUBLISHED', '2026-10-02T06:14:11.304Z', '2026-10-02T06:14:11.304Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO jobs (id, title, department, employment_type, workplace_type, location, experience_level, salary_range, featured, skills, summary, about_role, responsibilities, requirements, benefits, deadline, status, created_at, updated_at) VALUES ('performance-marketer-lead', 'Senior Performance Marketer', 'Digital Marketing', 'Full-time', 'In-Studio', 'Hyderabad', '3–5 Years', '₹7,00,000 – ₹12,00,000 / year', FALSE, 'Meta Ads Manager, Google Ads, GA4, Funnel CRO, Attribution', 'Drive exponential customer acquisition through disciplined media buying, paid search optimization, and rigorous funnel experimentation.', 'Lead digital marketing initiatives for rapid-growth businesses. You will manage active advertising budgets, optimize full-funnel conversions, and scale customer acquisition.', 'Plan, execute, and scale high-ROI paid campaigns across Meta Ads, Google Ads, and YouTube.
Analyze attribution funnels in GA4, adjust bidding algorithms, and reduce blended CAC.
Collaborate with content creators to script high-converting video and image ad creatives.
Deliver transparent weekly ROAS, CPM, and CPA reports to client stakeholders.', 'Proven track record managing performance ad budgets with verified ROAS gains.
Expert understanding of pixel setup, server-side CAPI tracking, and GA4 telemetry.
Analytical mindset with ability to dissect marketing funnel drops and CRO bottlenecks.', 'Direct profit-sharing / performance bonus incentives tied to campaign growth.
Freedom to experiment with modern automation and creative angle testing.', '2026-12-31', 'PUBLISHED', '2026-10-02T06:14:11.304Z', '2026-10-02T06:14:11.304Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO jobs (id, title, department, employment_type, workplace_type, location, experience_level, salary_range, featured, skills, summary, about_role, responsibilities, requirements, benefits, deadline, status, created_at, updated_at) VALUES ('ai-automation-engineer', 'AI & Automation Solutions Engineer', 'AI & Automation', 'Full-time', 'Remote', 'Remote (India)', '1–3 Years', '₹7,50,000 – ₹13,00,000 / year', TRUE, 'Python, FastAPI, OpenAI API, LangChain, Web Scraping, n8n', 'Build autonomous business workflows, intelligent customer communication agents, and LLM-powered backend processing pipelines.', 'Help businesses automate manual operational friction. You will build intelligent workflow agents, API bridges, and LLM pipelines that save hundreds of labor hours.', 'Develop custom automated pipelines connecting CRM, databases, and third-party APIs.
Implement retrieval-augmented generation (RAG) and semantic search microservices in Python.
Deploy asynchronous webhook listeners, queue workers, and data extraction bots.
Maintain high system uptime, logging, and error failover mechanisms.', 'Strong proficiency in Python, RESTful API consumption, and asynchronous architecture.
Experience integrating LLM APIs, function calling, and vector embeddings.
Familiarity with cloud functions, serverless environments, and automated testing.', 'Frontier work on modern AI deployment patterns.
100% remote flexibility with asynchronous communication culture.
Continuous credits for AI research tooling and API experiments.', '2026-12-31', 'PUBLISHED', '2026-10-02T06:14:11.304Z', '2026-10-02T06:14:11.304Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO jobs (id, title, department, employment_type, workplace_type, location, experience_level, salary_range, featured, skills, summary, about_role, responsibilities, requirements, benefits, deadline, status, created_at, updated_at) VALUES ('intern-frontend-engineer', 'Associate Frontend Developer Intern', 'Internship', 'Internship (3–6 Months)', 'Hybrid', 'Hyderabad', 'Students / Recent Graduates', 'Stipend + Placement Assistance', FALSE, 'JavaScript, React Basics, HTML5, CSS3, Git', 'Launch your engineering career with direct apprenticeship on live codebases, structured mentor feedback, and verified studio contribution credentials.', 'Designed for high-potential students and recent graduates seeking real-world software engineering apprenticeship. You will ship real code to production under senior oversight.', 'Implement UI components following clean code standards in React.
Fix responsive layout bugs across modern mobile and desktop browsers.
Participate in daily standups and learn professional Git branching conventions.', 'Foundational knowledge of JavaScript, modern ES6 syntax, and web fundamentals.
Completed personal or academic web projects that demonstrate initiative.
Eagerness to learn, accept constructive code reviews, and ship iteratively.', 'Hands-on experience with production codebases (zero toy todo apps).
Direct 1-on-1 mentorship from seasoned engineering leads.
Full placement assistance and immediate consideration for permanent full-time hiring.', '2026-12-31', 'PUBLISHED', '2026-10-02T06:14:11.304Z', '2026-10-02T06:14:11.304Z') ON CONFLICT (id) DO NOTHING;
