-- 5. TRAINING PROGRAMS
INSERT INTO training_programs (id, name, description, duration, mode, skills, eligibility, instructions, highlights, status, created_at, updated_at) VALUES ('fullstack-dev', 'Full Stack Development', 'An industry-oriented curriculum where candidates build production-level software using React, Next.js, Node.js, and relational databases under senior practitioner oversight.', '12 Weeks (Immersive)', 'In-Studio (Hyderabad) / Hybrid', 'React & Next.js, Node.js & Express, PostgreSQL / MySQL, REST APIs, Git Flow & CI/CD, Docker Basics', 'Final year engineering students, recent graduates, or aspiring developers with basic programming fundamentals seeking practical career preparation.', 'Submit your candidate application through the KODEWAR Careers portal. Shortlisted applicants will be invited for a diagnostic technical conversation.', '100% production codebases, zero toy todo apps
Daily standups, peer code reviews, and Git collaboration
Comprehensive placement assistance & portfolio audit
Direct consideration for open KODEWAR engineering roles', 'PUBLISHED', '2026-10-02T06:14:11.305Z', '2026-10-02T06:14:11.305Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO training_programs (id, name, description, duration, mode, skills, eligibility, instructions, highlights, status, created_at, updated_at) VALUES ('ui-ux-design', 'UI/UX Product Design', 'Master digital product design through real design sprints, wireframing, component design tokens, and user testing. Graduate with a production-ready portfolio case study.', '10 Weeks', 'In-Studio / Remote', 'Figma Mastery, Design Tokens & Systems, User Research & Wireframing, Interactive Prototyping, Developer Handoff, Heuristic Audits', 'Creative problem-solvers, graphic designers transitioning to product UI/UX, and students passionate about digital interfaces.', 'Apply with links to any existing sketches, visual projects, or design work. Prior tool experience in Figma is helpful but not mandatory.', 'Build 3 comprehensive, verified portfolio case studies
Learn how to collaborate with frontend engineers
Mentorship from practicing UI/UX product leads
Placement assistance and resume refinement', 'PUBLISHED', '2026-10-02T06:14:11.305Z', '2026-10-02T06:14:11.305Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO training_programs (id, name, description, duration, mode, skills, eligibility, instructions, highlights, status, created_at, updated_at) VALUES ('digital-marketing', 'Digital Marketing & Growth', 'Learn performance marketing by managing live ad budgets, analyzing GA4 telemetry, conducting funnel CRO, and scripting high-conversion creative hooks.', '8 Weeks', 'In-Studio / Hybrid', 'Meta Ads Manager, Google Ads & Search, GA4 & Tag Manager, Funnel CRO, Ad Copywriting, Short-form Video Strategy', 'Marketing graduates, founders, and career switchers wanting practical paid media experience without academic fluff.', 'Complete the candidate registration and submit your background interest. Live ad account access is provided during cohort sessions.', 'Hands-on experience with live ad spend budgets
Data-driven performance attribution telemetry
Industry-oriented training with agency practitioners
Placement assistance with active commercial partners', 'PUBLISHED', '2026-10-02T06:14:11.305Z', '2026-10-02T06:14:11.305Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO training_programs (id, name, description, duration, mode, skills, eligibility, instructions, highlights, status, created_at, updated_at) VALUES ('ai-automation', 'AI & Automation Engineering', 'Bridge software engineering and artificial intelligence. Build automated workflow agents, data ingestion pipelines, and LLM-powered backend tools.', '10 Weeks', 'In-Studio / Remote', 'Python Fundamentals, FastAPI Microservices, Web Scraping & Crawling, Agentic Automations, LLM API Integrations, Task Queues & Webhooks', 'Developers and engineering students with Python basics looking to specialize in high-demand automation and AI infrastructure.', 'Submit your profile along with your GitHub profile or code samples. Basic understanding of loops, functions, and HTTP APIs is recommended.', 'Deploy real agentic workflows and ETL pipelines
Learn asynchronous architecture and web crawling
Practical projects showcasing verifiable AI utility
Career preparation and technical interview coaching', 'PUBLISHED', '2026-10-02T06:14:11.305Z', '2026-10-02T06:14:11.305Z') ON CONFLICT (id) DO NOTHING;
